package kec.allocator;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
public class MainApp {
 private static final Scanner IN=new Scanner(System.in);private static final IncubatorDAO DAO=new IncubatorDAO();private static final FileProcessor FP=new FileProcessor();
 public static void main(String[] args){System.out.println("KEC STUDENT INNOVATION & STARTUP GRANT ALLOCATOR");try(var c=DBConnection.getConnection()){System.out.println("Database connected.");}catch(Exception e){System.out.println("Database connection failed: "+e.getMessage());System.out.println("Check MySQL, config/db.properties and Connector/J in lib/.");return;}
  while(true){System.out.println("\n1. Import proposals from CSV\n2. Evaluate all proposals (parallel)\n3. View rankings/results\n4. Generate sanction letters\n5. Show ISM\n6. Exit");System.out.print("Choose: ");String choice=IN.nextLine().trim();try{switch(choice){case "1"->importCsv();case "2"->evaluate();case "3"->show();case "4"->letters();case "5"->System.out.printf(Locale.US,"ISM = Rs. %.2f per evaluated proposal%n",DAO.ism());case "6"->{System.out.println("Goodbye.");return;}default->System.out.println("Choose 1 to 6.");}}catch(Exception e){System.out.println("Operation failed: "+e.getMessage());}}}
 private static void importCsv()throws Exception{System.out.print("CSV path [data/sample_proposals.csv]: ");String s=IN.nextLine().trim();Path p=s.isEmpty()?Path.of("data","sample_proposals.csv"):Path.of(s);List<StartupProposal> list=FP.readCsv(p);for(StartupProposal x:list)DAO.saveProposal(x);System.out.println("Imported/updated "+list.size()+" proposal(s).");}
 private static void evaluate()throws Exception{List<StartupProposal> list=DAO.all();if(list.isEmpty()){System.out.println("Import proposals first.");return;}ExecutorService pool=Executors.newFixedThreadPool(Math.max(2,Runtime.getRuntime().availableProcessors()));try{List<Future<EvaluationResult>> fs=new ArrayList<>();for(StartupProposal p:list)fs.add(pool.submit(new ScoringWorker(p)));for(Future<EvaluationResult> f:fs){EvaluationResult r=f.get();DAO.saveResult(r);System.out.printf(Locale.US,"%s: %.2f - %s%n",r.code(),r.score(),r.status());}}finally{pool.shutdown();}System.out.println("Parallel evaluation finished.");}
 private static void show()throws Exception{List<String[]> rows=DAO.results();if(rows.isEmpty()){System.out.println("No results. Evaluate proposals first.");return;}System.out.printf("%-15s %-25s %8s %-8s %13s %-22s %-15s%n","CODE","STARTUP","SCORE","TIER","GRANT(Rs)","STATUS","DISBURSEMENT");for(String[] r:rows)System.out.printf(Locale.US,"%-15s %-25.25s %8s %-8s %13s %-22s %-15s%n",r[0],r[1],r[2],r[3],r[4],r[5],r[6]);}
 private static void letters()throws Exception{List<String[]> rows=DAO.results();if(rows.isEmpty()){System.out.println("Evaluate proposals first.");return;}FP.letters(rows,Path.of("output"));System.out.println("Letters saved in output/.");}
}
